<div class="d-flex justify-content-between align-items-end mb-4"><div><span class="lh-kicker">Super Admin</span><h1 class="lh-page-title mb-1">Event review</h1><p class="text-secondary mb-0">Approve useful opportunities for the shared calendar.</p></div><a class="btn btn-outline-primary" href="/calendar">View calendar</a></div><div class="d-grid gap-3"><?php foreach ($events as $event): ?><article class="lh-card p-4"><div class="row g-4 align-items-start"><div class="col-lg-8"><div class="small text-primary fw-semibold"><?= e(date('D, M j, Y', strtotime($event['event_date']))) ?> · <?= e($event['location']) ?></div><h2 class="h4 mt-2 mb-2"><?= e($event['title']) ?></h2><p class="text-secondary mb-2"><?= nl2br(e($event['description'])) ?></p><div class="small text-secondary">Submitted by <?= e($event['submitter_name']) ?> · Organizer: <?= e($event['organizer']) ?></div><?php if ($event['material_request']): ?><div class="alert alert-light mt-3 mb-0"><strong>Materials requested:</strong> <?= e($event['material_request']) ?></div><?php endif; ?></div><div class="col-lg-4"><form method="post" action="/events/<?= (int)$event['id'] ?>/review" class="d-grid gap-2"><input type="hidden" name="_token" value="<?= e($_SESSION['csrf']) ?>"><textarea class="form-control" name="reason" rows="2" placeholder="Reason if rejecting"></textarea><div class="d-flex gap-2"><button class="btn btn-lh-primary flex-grow-1" name="status" value="approved" type="submit">Approve</button><button class="btn btn-outline-danger" name="status" value="rejected" type="submit">Reject</button></div></form></div></div></article><?php endforeach; if (!$events): ?><div class="lh-card p-5 text-center text-secondary">No events awaiting review.</div><?php endif; ?></div>
